"use client";
import { useEffect, useRef, useState } from "react";
import { Paperclip, Camera, Send, Smile } from "lucide-react";
import { PlaceholdersAndVanishInput } from "@/components/ui/placeholders-and-vanish-input";
import { Picker, EmojiType } from "ms-3d-emoji-picker";
import Sidebar from "@/app/Components/Sidebar";
import Header from "@/app/Components/Header";
import ChatWindow from "./Components/ChatWindow";

export default function Home() {
  const [messages, setMessages] = useState([
    {
      id: 1,
      text: "Hello! How are you?",
      sender: "receiver",
      time: "10:05 AM",
    },
    {
      id: 2,
      text: "Hey! I'm good. What about you?",
      sender: "sender",
      time: "10:06 AM",
    },
    {
      id: 3,
      text: "I'm doing great, thanks!",
      sender: "receiver",
      time: "10:07 AM",
    },
  ]);
  type Message = {
    id: number;
    text: string;
    sender: "sender" | "receiver";
    time: string;
    file?: {
      name: string;
      type: string;
      url: string;
    } | null;
  };

  const [input, setInput] = useState("");
  const [file, setFile] = useState<File | null>(null);
  const [fileURL, setFileURL] = useState<string | null>(null);
  const [showPicker, setShowPicker] = useState<boolean>(false);
  const placeholder: string[] = ["Type a message..."];
  const messagesEndRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);
  useEffect(() => {
    return () => {
      if (fileURL) URL.revokeObjectURL(fileURL);
    };
  }, [fileURL]);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = event.target.files?.[0] || null;
    setFile(selectedFile);

    if (selectedFile) {
      const url = URL.createObjectURL(selectedFile);
      setFileURL(url);
    }
  };

  const handleSend = (): void => {
    if (input.trim() || file) {
      let fileURLToSend = file ? URL.createObjectURL(file) : null;

      const newMessage: Message = {
        id: messages.length + 1,
        text: input,
        sender: "sender",
        time: new Date().toLocaleTimeString([], {
          hour: "2-digit",
          minute: "2-digit",
        }),
        file: file
          ? {
              name: file.name,
              type: file.type,
              url: fileURLToSend!,
            }
          : null,
      };

      setMessages([...messages, newMessage]);
      setInput("");
      setFile(null);
      setFileURL(null);
    }
  };

  return (
    <>
      <div className="flex items-center justify-center h-screen bg-gradient-to-br from-[#1e1e2e] to-[#101018]">
        <div className="w-full h-full rounded-2xl text-white glassEffect overflow-hidden">
          <div className="flex">
            <Sidebar />
            <div className="ml-[320px] w-full">
              <ChatWindow />
            </div>
          </div>
        </div>
      </div>
    
    </>
  );
}
